-- replica.sql (17A): REPLICA of the captured prod storage + profile_content state. ALL DATA SYNTHETIC; no prod connection.
-- Bucket rows, the storage.objects policies, profile_content columns/policies/ACL are the CAPTURED ones (baseline/PROD-FACTS-17A.md). Assumptions (NOT captured, marked A:):
--   A: predicates of the owner-scoped playlist-covers / vs-entries INSERT/UPDATE/DELETE policies and the profile_content insert/update/delete policies (only their NAMES/intent are captured);
--      public.is_admin() / vs_is_admin() bodies; profile_owners RLS ("read own"); vs_entries columns; storage.objects column set = documented Supabase columns (owner_id is the uploader uid as text).
--   REAL STORAGE API BEHAVIOUR (public URL serving, signed URLs, MIME enforcement, move/copy) is NOT reproducible on plain Postgres: public URL serving is modelled by public_url_readable().
-- Roles anon / authenticated / service_role / postgres / authenticator are created by the harness (NOSUPERUSER stand-ins, service_role has BYPASSRLS like Supabase).
create schema auth;
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub', true), '')::uuid $$;
grant usage on schema auth to anon, authenticated, service_role;
create table auth.users (id uuid primary key, email text);
grant select on auth.users to service_role;

create table public.app_users (id uuid primary key, handle text, email text, is_admin boolean not null default false, vs_reviewer boolean not null default false);
grant select on public.app_users to authenticated, service_role;
-- A: admin helpers: SECURITY DEFINER, executable by anon/authenticated (the web client calls vs_is_admin() as an RPC)
create function public.is_admin() returns boolean language sql stable security definer set search_path = public as $$ select coalesce((select a.is_admin from public.app_users a where a.id = auth.uid()), false) $$;
revoke all on function public.is_admin() from public; grant execute on function public.is_admin() to anon, authenticated, service_role;
create function public.vs_is_admin() returns boolean language sql stable security definer set search_path = public as $$ select coalesce((select a.is_admin or a.vs_reviewer from public.app_users a where a.id = auth.uid()), false) $$;
revoke all on function public.vs_is_admin() from public; grant execute on function public.vs_is_admin() to anon, authenticated, service_role;

create table public.profile_owners (profile_slug text not null, owner_id uuid not null, primary key (profile_slug, owner_id));
alter table public.profile_owners enable row level security;
grant all on public.profile_owners to anon, authenticated, service_role;
create policy profile_owners_read_own on public.profile_owners for select to authenticated using (owner_id = auth.uid());   -- A

-- profile_content: CAPTURED columns, RLS on, ACL arwdDxtm for anon+authenticated+service_role, "read all" USING true
create table public.profile_content (id uuid primary key default gen_random_uuid(), profile_slug text, kind text, data jsonb, created_by uuid, created_at timestamptz default now(), archived boolean);
alter table public.profile_content enable row level security;
grant all on public.profile_content to anon, authenticated, service_role;
create policy "profile_content read all" on public.profile_content for select to public using (true);
create policy "profile_content insert own" on public.profile_content for insert to authenticated with check (created_by = auth.uid() and exists (select 1 from public.profile_owners po where po.profile_slug = profile_content.profile_slug and po.owner_id = auth.uid()));   -- A predicate
create policy "profile_content update own" on public.profile_content for update to authenticated using (exists (select 1 from public.profile_owners po where po.profile_slug = profile_content.profile_slug and po.owner_id = auth.uid())) with check (exists (select 1 from public.profile_owners po where po.profile_slug = profile_content.profile_slug and po.owner_id = auth.uid()));   -- A predicate
create policy "profile_content delete own" on public.profile_content for delete to authenticated using (exists (select 1 from public.profile_owners po where po.profile_slug = profile_content.profile_slug and po.owner_id = auth.uid()));   -- A predicate
-- a table whose RLS sub-select reads profile_content as INVOKER (post_saves embeds profile_content(...) in the web client)
create table public.post_saves (id bigint generated by default as identity primary key, user_id uuid, content_id uuid references public.profile_content(id));
alter table public.post_saves enable row level security; grant select, insert on public.post_saves to authenticated; create policy post_saves_own on public.post_saves for all to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());

-- vs_entries (A: columns) - pending vs approved
create table public.vs_entries (id bigint generated by default as identity primary key, user_id uuid, title text, status text not null default 'pending', cover_url text);
alter table public.vs_entries enable row level security;
grant select on public.vs_entries to anon, authenticated, service_role;
create policy vs_entries_read on public.vs_entries for select to anon, authenticated using (status = 'approved' or user_id = auth.uid());
-- tables referencing storage URLs as text / jsonb (for the P3c references guard + inventory queries)
create table public.events (id bigint generated by default as identity primary key, slug text, title text, cover_url text);
create table public.vs_entry_media (id bigint generated by default as identity primary key, entry_id bigint, url text);
create table public.notes_misc (id int generated by default as identity primary key, body text);
create table public.community_chat_messages (id bigint generated by default as identity primary key, body text, image_url text);
grant select on public.events, public.vs_entry_media, public.notes_misc, public.community_chat_messages to anon, authenticated, service_role;
-- the 11 backup tables (original ACL = ALL for anon+authenticated: A, the pre-Grok state)
do $bak$ declare t text; begin
  foreach t in array array['_bak_agent_knowledge_corrupt_20260814','_bak_app_users_seed_20260815','_bak_cron_config_20260814','_bak_events_no_image_20260815','_bak_profile_content_corrupt_20260815','_bak_profile_content_orphan_articles_20260815','_bak_profile_meta_20260814','_bak_profile_owners_20260815','_bak_venue_queue_20260818','_bak_venues_20260814','_bak_venues_20260818'] loop
    execute format('create table public.%I (id int, v text)', t); execute format('grant all on public.%I to anon, authenticated, service_role', t); end loop; end $bak$;

-- ============================================================ storage (replica of Supabase storage schema columns that matter)
create schema storage;
grant usage on schema storage to anon, authenticated, service_role;
create table storage.buckets (id text primary key, name text not null unique, owner uuid, created_at timestamptz default now(), updated_at timestamptz default now(), public boolean default false, avif_autodetection boolean default false, file_size_limit bigint, allowed_mime_types text[], owner_id text);
create table storage.objects (id uuid primary key default gen_random_uuid(), bucket_id text references storage.buckets(id), name text, owner uuid, created_at timestamptz default now(), updated_at timestamptz default now(), last_accessed_at timestamptz default now(), metadata jsonb, path_tokens text[] generated always as (string_to_array(name, '/')) stored, version text, owner_id text, user_metadata jsonb);
create unique index bucketid_objname on storage.objects (bucket_id, name);
create function storage.foldername(name text) returns text[] language plpgsql as $$ declare _parts text[]; begin select string_to_array(name, '/') into _parts; return _parts[1:array_length(_parts,1)-1]; end $$;
create function storage.filename(name text) returns text language plpgsql as $$ declare _parts text[]; begin select string_to_array(name, '/') into _parts; return _parts[array_length(_parts,1)]; end $$;
alter table storage.objects enable row level security;
alter table storage.buckets enable row level security;
grant all on storage.objects, storage.buckets to anon, authenticated, service_role;
-- the models of the Storage API's public-URL path: a bucket flagged public serves its objects WITHOUT any RLS policy
create function public.public_url_readable(p_bucket text, p_name text) returns boolean language sql stable security definer set search_path = '' as $$ select coalesce((select b.public from storage.buckets b where b.id = p_bucket), false) and exists (select 1 from storage.objects o where o.bucket_id = p_bucket and o.name = p_name) $$;
grant execute on function public.public_url_readable(text, text) to anon, authenticated, service_role;

