-- CAPTURED storage.objects policies (the four bucket-wide SELECTs, the chat upload, the owner-scoped playlist-covers / vs-entries writes) + A: predicates for the owner-scoped ones
create policy agent_posts_public_read on storage.objects for select to public using (bucket_id = 'agent-posts');
create policy "chat images public read" on storage.objects for select to public using (bucket_id = 'chat-images');
create policy "chat images auth upload" on storage.objects for insert to authenticated with check (bucket_id = 'chat-images');
create policy "playlist covers are publicly readable" on storage.objects for select to public using (bucket_id = 'playlist-covers');
create policy "playlist covers owner insert" on storage.objects for insert to authenticated with check (bucket_id = 'playlist-covers' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "playlist covers owner update" on storage.objects for update to authenticated using (bucket_id = 'playlist-covers' and (storage.foldername(name))[1] = auth.uid()::text) with check (bucket_id = 'playlist-covers' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "playlist covers owner delete" on storage.objects for delete to authenticated using (bucket_id = 'playlist-covers' and (storage.foldername(name))[1] = auth.uid()::text);
create policy vs_media_read on storage.objects for select to public using (bucket_id = 'vs-entries');
create policy vs_media_insert on storage.objects for insert to authenticated with check (bucket_id = 'vs-entries' and (storage.foldername(name))[1] = auth.uid()::text);
create policy vs_media_update on storage.objects for update to authenticated using (bucket_id = 'vs-entries' and (storage.foldername(name))[1] = auth.uid()::text) with check (bucket_id = 'vs-entries' and (storage.foldername(name))[1] = auth.uid()::text);
create policy vs_media_delete on storage.objects for delete to authenticated using (bucket_id = 'vs-entries' and (storage.foldername(name))[1] = auth.uid()::text);
-- unrelated policy on another bucket (must stay byte-identical through every pack): household-scoped manatua read (A: simplified)
create policy manatua_media_member_read on storage.objects for select to public using (bucket_id = 'manatua-media' and auth.uid() is not null);
